INSERT INTO public.periods (id,wikidata_id,label_fr,label_en,description_fr,description_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic,wikipedia_title_fr,wikipedia_title_en) VALUES
('13f5f86e-79f2-4a09-9a68-6553ecfb4971','Q124205596','Optimum climatique du Miocène moyen','Middle Miocene Climatic Optimum','Un intervalle chaud interrompt le refroidissement du Cénozoïque, avant une nouvelle expansion de la calotte antarctique.','A warm interval interrupts Cenozoic cooling before renewed expansion of the Antarctic ice sheet.','M17','M14.7',17000000,14700000,false,NULL,'Middle Miocene Climatic Optimum'),
('b543ef73-f7f4-4d92-b60c-3f9ce3e5dec3','Q7205011','Période chaude du Pliocène moyen','Mid-Piacenzian Warm Period','Un climat plus chaud que le climat préindustriel, avec des calottes réduites et un niveau marin plus élevé, sert de référence pour étudier la réponse à long terme du système climatique.','A climate warmer than pre-industrial conditions, with reduced ice sheets and higher sea levels, provides a reference for studying the long-term response of the climate system.','M3.3','M3',3300000,3000000,false,NULL,'Mid-Piacenzian Warm Period'),
('c2ad4965-c02c-4553-a712-0a66154adc52',NULL,'Interstade de Bølling-Allerød','Bølling–Allerød Interstadial','Un réchauffement rapide de l’Atlantique Nord interrompt la dernière déglaciation, avant le retour au froid du Dryas récent.','Rapid North Atlantic warming interrupts the last deglaciation before the return to cold conditions during the Younger Dryas.','K14.7','10900 BCE',14700,12925.5947980835,false,NULL,'Bølling–Allerød Interstadial'),
('7590b9ca-3819-4821-aab8-418bdaa4cdaa','Q1785837','Refroidissement de 8200 ans avant le présent','8.2-kiloyear cooling event','Un afflux d’eau douce dans l’Atlantique Nord perturbe la circulation océanique et provoque un refroidissement particulièrement marqué autour du Groenland.','A freshwater influx into the North Atlantic disrupts ocean circulation and causes cooling particularly pronounced around Greenland.','6300 BCE','6140 BCE',8325.68788501027,8165.69062286105,false,'Événement climatique de 8200 AP','8.2-kiloyear event'),
('a71055d1-4f19-42d1-bc61-870b9bee0a4e','Q827568','Minimum de Maunder','Maunder Minimum','La raréfaction des taches solaires coïncide avec une partie du Petit Âge glaciaire, dont le refroidissement a aussi des causes volcaniques et océaniques.','Scarce sunspots coincide with part of the Little Ice Age, whose cooling also has volcanic and oceanic causes.','1645','1715',381.849418206708,311.853524982888,false,'Minimum de Maunder','Maunder Minimum');
INSERT INTO public.events (id,wikidata_id,label_fr,label_en,description_fr,description_en,date,date_years_bp,wikipedia_title_fr,wikipedia_title_en) VALUES
('bc849061-ceca-405c-aa50-ace9260a55a3',NULL,'Fourier décrit le rôle thermique de l’atmosphère','Fourier describes the atmosphere’s thermal role','Joseph Fourier explique que l’atmosphère retient une partie de la chaleur terrestre, posant les bases de la compréhension de l’effet de serre.','Joseph Fourier explains that the atmosphere retains some of Earth’s heat, laying foundations for understanding the greenhouse effect.','1824',202.856947296372,'Joseph Fourier','Joseph Fourier'),
('32edc091-3869-481e-a6b1-5e147ab4a109',NULL,'Eunice Foote expérimente l’échauffement du CO₂','Eunice Foote experiments with CO₂ warming','Eunice Newton Foote observe qu’un récipient rempli de CO₂ chauffe davantage au soleil et suggère qu’une atmosphère enrichie en ce gaz serait plus chaude.','Eunice Newton Foote observes that a container filled with CO₂ warms more in sunlight and suggests that an atmosphere richer in this gas would be warmer.','1856',170.856947296372,'Eunice Newton Foote','Eunice Newton Foote'),
('24c4b458-f03d-45c1-8558-499a0f7bd8ac',NULL,'Tyndall mesure l’absorption de la chaleur par les gaz','Tyndall measures heat absorption by gases','John Tyndall montre en laboratoire que la vapeur d’eau et le CO₂ absorbent le rayonnement thermique, établissant un mécanisme physique de l’effet de serre.','John Tyndall shows in the laboratory that water vapour and CO₂ absorb thermal radiation, establishing a physical mechanism of the greenhouse effect.','1859',167.856262833676,'John Tyndall (physicien)','John Tyndall'),
('94b1b316-e300-433b-8b26-a3a9a0fef5e8',NULL,'Callendar relie les émissions de CO₂ au réchauffement observé','Callendar links CO₂ emissions to observed warming','Guy Stewart Callendar rassemble des mesures de température et de CO₂ et propose que la combustion des énergies fossiles contribue au réchauffement mesuré.','Guy Stewart Callendar combines temperature and CO₂ measurements and proposes that fossil fuel combustion contributes to observed warming.','1938-04',88.611909650924,'Guy Stewart Callendar','Guy Stewart Callendar'),
('80184abf-ef0d-40b7-bb80-ac9d0370d5b8',NULL,'Milanković publie sa synthèse sur les cycles orbitaux','Milanković publishes his synthesis on orbital cycles','Milutin Milanković rassemble ses calculs reliant les variations de l’orbite et de l’axe terrestres à la répartition de l’ensoleillement et aux glaciations.','Milutin Milanković brings together calculations linking variations in Earth’s orbit and axis to the distribution of sunlight and glaciations.','1941',85.8576317590691,'Milutin Milanković','Milutin Milanković'),
('ab5379ac-818c-4528-8cb5-3193f07e7a75','Q56874477','Manabe et Wetherald modélisent le réchauffement par le CO₂','Manabe and Wetherald model CO₂-driven warming','Un modèle radiatif-convectif de l’atmosphère quantifie le réchauffement dû au doublement du CO₂ et le rôle amplificateur de la vapeur d’eau.','A radiative-convective atmospheric model quantifies warming from doubled CO₂ and the amplifying role of water vapour.','1967-05',59.5304585900068,'Thermal Equilibrium of the Atmosphere with a Given Distribution of Relative Humidity','Thermal Equilibrium of the Atmosphere with a Given Distribution of Relative Humidity'),
('92f8ff4b-3c89-4c7a-a26c-75a9a01b3628',NULL,'Les sédiments marins étayent la théorie orbitale des glaciations','Marine sediments support the orbital theory of ice ages','James Hays, John Imbrie et Nicholas Shackleton montrent que les archives océaniques portent les rythmes orbitaux attendus par la théorie de Milanković.','James Hays, John Imbrie and Nicholas Shackleton show that ocean records contain the orbital rhythms expected from Milanković’s theory.','1976',50.8596851471595,NULL,NULL),
('f5962488-db30-4571-973f-22e531eca832','Q5972980','Premier rapport d’évaluation du GIEC','First IPCC Assessment Report','Le GIEC rassemble les connaissances sur le changement climatique et souligne la nécessité d’une coopération internationale face aux émissions de gaz à effet de serre.','The IPCC brings together knowledge on climate change and highlights the need for international cooperation on greenhouse gas emissions.','1990',36.8583162217659,'Premier rapport d''évaluation du GIEC','IPCC First Assessment Report'),
('a065e7e5-8cb3-4d5e-a579-c0dee83c6d5d','Q208645','Adoption de la Convention-cadre sur le climat','Adoption of the UN Framework Convention on Climate Change','Les Nations unies adoptent le cadre de coopération internationale visant à stabiliser les concentrations de gaz à effet de serre.','The United Nations adopts a framework for international cooperation to stabilise greenhouse gas concentrations.','1992-05-09',34.5065023956194,'Convention-cadre des Nations unies sur les changements climatiques','United Nations Framework Convention on Climate Change'),
('0d54559d-5c03-4f2c-9e8f-31ace60b89d5',NULL,'Le GIEC établit sans équivoque l’origine humaine du réchauffement','IPCC establishes unequivocal human influence on warming','Le volet physique du sixième rapport d’évaluation conclut que l’influence humaine a réchauffé l’atmosphère, les océans et les terres.','The physical science contribution to the Sixth Assessment Report concludes that human influence has warmed the atmosphere, ocean and land.','2021-08-09',5.25530458590007,'Sixième rapport d''évaluation du GIEC','IPCC Sixth Assessment Report'),
('a3c466d2-7d87-4bfb-a8bf-aa7de6ade069',NULL,'Première année civile au-dessus de +1,5 °C selon Copernicus','First calendar year above +1.5°C according to Copernicus','La température moyenne mondiale de l’année dépasse de plus de 1,5 °C la référence préindustrielle selon Copernicus ; ce constat annuel ne vaut pas franchissement du seuil de Paris sur le long terme.','The year’s global mean temperature exceeds the pre-industrial baseline by more than 1.5°C according to Copernicus; this annual observation does not mean the long-term Paris threshold has been crossed.','2024',2.85968514715948,NULL,NULL);
